// prompts 表自身冗余保存当前版本的全部字段，供列表筛选与判定直接使用，
// 不必每次联表 prompt_versions。每次修改都要同步，否则列表与详情会给出不同取值。
func (q *Queries) UpdatePromptContent(ctx context.Context, arg UpdatePromptContentParams) (Prompt, error) {
	row := q.db.QueryRow(ctx, updatePromptContent,
		arg.ID,
		arg.Title,
		arg.Body,
		arg.Description,
		arg.CategoryID,
		arg.AbilityID,
		arg.DifficultyID,
		arg.Visibility,
		arg.SensitiveLevel,
	)
	var i Prompt
	err := row.Scan(
		&i.ID,
		&i.Title,
		&i.Body,
		&i.Description,
		&i.CategoryID,
		&i.AbilityID,
		&i.DifficultyID,
		&i.Visibility,
		&i.SensitiveLevel,
		&i.UploaderID,
		&i.OriginalUploaderID,
		&i.CurrentVersionID,
		&i.LatestVersionNo,
		&i.MajorModified,
		&i.CommentCount,
		&i.FavoriteCount,
		&i.DeletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
